var s=[{title:`Como é um esforço constante`,text:`A sua frequência cardíaca não vai ser uma linha perfeitamente plana. O ritmo e a respiração podem variar com subidas, calor ou fadiga, enquanto o esforço global se mantém controlado. Escolha uma atividade que consiga continuar sem paragens frequentes nem técnica desleixada.`},{title:`Escolha uma intensidade`,text:`Em muitas sessões de condição física geral, a intensidade moderada dá trabalho mas ainda permite manter uma conversa. O teste da conversa costuma ser mais útil do que perseguir uma velocidade ou um número de frequência cardíaca definidos. As pessoas treinadas conseguem fazer trabalho contínuo vigoroso, mas os iniciantes costumam dar-se melhor se começarem com suavidade.`},{title:`Aumente o tempo antes da velocidade`,text:`Comece com uma quantidade prática, como 10–20 minutos de caminhada rápida ou de bicicleta fácil. Aumente a sessão em pequenos passos ao longo do tempo e só depois pense num ritmo mais rápido ou em mais resistência da máquina. Se aumentar ao mesmo tempo o tempo, a velocidade e a frequência, é mais difícil perceber o que causa a sua fadiga e como recupera.`},{title:`Adapte-se às condições`,text:`Caminhar e andar de bicicleta são escolhas mais fáceis se quiser menos impacto, enquanto o jogging acrescenta aterragens repetidas. Em espaço fechado, as máquinas permitem manter as definições bastante constantes, mas ao ar livre as inclinações e o tempo alteram a sensação do mesmo ritmo apresentado. Use a dificuldade que sente para comparar as sessões de forma justa. Está a melhorar quando o mesmo percurso parece mais fácil ou uma sessão confortável fica mais longa, e não precisa de levar todos os treinos ao limite.`}];var o=[{label:`Recomendações do CDC sobre atividade física para adultos`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`},{label:`CDC: medir a intensidade da atividade e o teste da conversa`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`CDC: exercício com calor`,url:`https://www.cdc.gov/heat-health/risk-factors/heat-and-athletes.html`}];var i={sections:s,sources:o};export{i as default,s as sections,o as sources};